SignalWaitCheckRate(signal* Sig,float Slope,long time)
{
  long timecopy;
  float value;
  float startVal, endVal,diffVal;
  timecopy=0;
  while(1)
  {
    startVal=$Sig;
    testwaitfortimeout(5);
    endVal=$Sig;
    diffVal=abs(endVal)-abs(startVal);
    if(diffVal>=Slope)
    {
      TestStepPass("","信号斜率%.2f达到目标值：%.2f", diffVal, Slope);
      break;
    }
    timecopy+=5;
    if(timecopy>=time)
    {
      TestStepFail("","信号斜率%.2f没有达到目标值：%.2f", diffVal, Slope);
      break;
    }
  }
}

