int CompareTwoArrary(byte target[] ,byte source[],int offset ,int length )
{

  int i ;
  int retVal;

  if((elcount(target)> length) || (elcount(target) > elcount(source)) )
  {
    write("arrary length is wrong!");
    return gcNok ;
  }

  for(i= offset;i< length ;i++)
  {
    if(target[i -offset] != source[i])
    {
      return gcNok ;
    }
  } 
 return gcOk;
}

